#!/usr/bin/env python3
"""Generate the review PDF after the real emulator walkthrough has passed."""
from pathlib import Path
import hashlib,json
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/PocketMemory-Plans-Project-Brief.pdf'
log=(ROOT/'docs/evidence/test-meta-llama.txt').read_text()
assert 'ALL CHECKS PASSED' in log and '\nFAIL:' not in log
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitlePM',fontName='Helvetica-Bold',fontSize=35,leading=39,textColor=colors.HexColor('#201e25'),spaceAfter=18))
styles.add(ParagraphStyle(name='SubPM',fontName='Helvetica',fontSize=16,leading=23,textColor=colors.HexColor('#5e5667'),spaceAfter=18))
styles.add(ParagraphStyle(name='H1PM',fontName='Helvetica-Bold',fontSize=24,leading=29,spaceAfter=16,textColor=colors.HexColor('#201e25')))
styles.add(ParagraphStyle(name='H2PM',fontName='Helvetica-Bold',fontSize=13,leading=18,spaceBefore=12,spaceAfter=6))
styles.add(ParagraphStyle(name='BodyPM',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=9,textColor=colors.HexColor('#38323f')))
styles.add(ParagraphStyle(name='SmallPM',fontName='Helvetica',fontSize=8.4,leading=12,spaceAfter=7,textColor=colors.HexColor('#5e5667')))
styles.add(ParagraphStyle(name='TagPM',fontName='Helvetica-Bold',fontSize=10,leading=14,spaceAfter=16,textColor=colors.HexColor('#0866ff')))
def p(t,style='BodyPM'):return Paragraph(escape(t).replace('\n','<br/>'),styles[style])
def h(t):return p(t,'H1PM')
def sub(t):return p(t,'H2PM')
def screenshot(name,width=180):
 from PIL import Image as PIL
 f=ROOT/'docs/images'/name
 with PIL.open(f) as im:w,hh=im.size
 return Image(str(f),width=width,height=width*hh/w)
def table(rows,widths):
 t=Table([[p(str(c),'SmallPM') for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#adf2eb')),('BOX',(0,0),(-1,-1),.7,colors.HexColor('#201e25')),('INNERGRID',(0,0),(-1,-1),.3,colors.HexColor('#d8d0e1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
 return t
story=[]
story += [p('META GLOBAL AI DEVELOPER HACKATHON 2026','TagPM'),p('Pocket Memory\nBuilt with Llama','TitlePM'),p('Saved instructions.\nReviewed action.','SubPM')]
hero=Table([[screenshot('02-review.png',185),[p('A local planner.\nA bounded task engine.','H2PM'),p('Meta Llama 3.2 3B selects relevant source actions. Application rules order workflow phases. The user inspects the evidence and approves a local task batch.'),p('Changed sources block old proposals. Repeated apply avoids duplicates. Guarded undo protects completed or changed work.'),p('Llama hackathon edition\nIndie Developer Track\nBuild for Your World\nPrepared 1 November 2026','SmallPM'),p('Manthan Dhole | Solo developer','SmallPM')]]],colWidths=[215,288]);hero.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP')]))
story += [hero,Spacer(1,12),p('Actual app captures, fictional data and real Meta inference. The narrated preview is edited and makes no speed or physical-phone performance claim.','SmallPM'),PageBreak()]
story += [h('The client-day plan'),p('Five fictional notes contain arrival instructions, equipment, venue, follow-up and a separate party. The goal is to prepare for and follow up on the Lakeview client demo. Llama selects relevant IDs; the application copies exact source action text.'),table([['Source','Relevant detail'],['Arrival','2 November 2026; arrive 09:45 for the 10:00 demo.'],['Equipment','Bring the prototype tablet, USB-C hub and printed storyboard.'],['Venue change','East entrance / Cedar becomes west entrance / Orchid.'],['Follow-up','Send Mira the revised storyboard for approval.'],['Distractor','Blue balloons belong to a different event and are excluded.']],[100,403]),Spacer(1,14)]
shots=Table([[screenshot('04-stale.png',145),screenshot('05-ready-to-apply.png',145)],[p('An edited source blocks the old batch.','SmallPM'),p('Rebuild, inspect and explicitly approve.','SmallPM')]],colWidths=[251,252]);shots.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('ALIGN',(0,0),(-1,0),'CENTER')]));story += [shots,PageBreak()]
story += [h('A model with bounded authority'),p('Source snapshot -> candidate actions -> Meta Llama selects IDs -> validation -> human review -> atomic task batch -> guarded undo.'),table([['Boundary','Implementation'],['Sources','Immutable note list and a hash of that same snapshot. Up to 50 notes.'],['Candidates','Goal keyword ranking; up to 8 notes and 16 explicit action sentences.'],['Inference','Meta Llama 3.2 3B Instruct Q4_K_M through a new JNI adapter and public llama.cpp.'],['Output','Grammar-constrained JSON: one steps array, allowed integer IDs. Java rejects unknown, duplicate, fractional or extra fields. Up to 6 actions.'],['Review','Exact source text and source revisions remain inspectable. Llama cannot create tasks itself.'],['Apply','Source freshness, deduplication, task writes and batch links share one SQLite transaction.'],['Undo','Check every created task first; preserve reused, completed or changed work.'],['Recovery','Job-scoped cancellation, bounded inference, persisted proposals/tasks and no automatic re-execution on restart.']],[94,409]),sub('Pinned model identity'),p('Upstream: meta-llama/Llama-3.2-3B-Instruct\nGGUF: bartowski/Llama-3.2-3B-Instruct-GGUF\nRevision: 5ab33fa94d1d04e903623ae72c95d1696f09f9e8\nSize: 2,019,377,696 bytes','SmallPM'),p('SHA-256: 6c1a2b41161032677be168d354123594c0e6e67d2b9227c84f296ad037c728ff','SmallPM'),p('Built with Llama. Model weights are imported separately after size/hash verification. The model is governed by its Llama 3.2 Community License and Acceptable Use Policy.','SmallPM'),PageBreak()]
checks=[]
for line in log.splitlines():
 if line.startswith('PASS: ') and line not in checks:checks.append(line)
story += [h('Inspectable verification'),p('Build and Android lint passed. The real ARM64 Android 15 emulator walkthrough runs in airplane mode. An independent restart test verifies persisted task identities and batch links.'),table([['Test','Observed behavior'],['Meta inference','Actual Llama selects the relevant client actions and excludes the separate party. Raw ID output is recorded.'],['Ordering','Application-owned phase rules put preparation before arrival, venue access and explicit follow-up in the verified proposal.'],['Output validation','Unknown IDs, duplicate IDs, fractions, extra fields and prose are refused.'],['Human review','Planning creates zero tasks; the real review control commits the chosen batch.'],['Source changes','An outdated proposal rejects the whole transaction and creates zero partial tasks. A new Llama run uses Orchid.'],['Idempotency','Repeating apply does not duplicate the batch.'],['Undo','A completed created task blocks all deletion. Unchanged created tasks can be removed; reapply requires explicit review.'],['Restart','Tasks and links survive actual process restart without automatic inference or duplicate execution.']],[100,403]),sub('Limits of the evidence'),p('Structural validation is not proof of relevance or correct phase grouping. Llama may omit a useful action or select a wrong one. Candidate extraction is bounded and expects explicit English action sentences. Plans use one user-selected date and do not infer deadlines or send messages. Physical-phone performance, battery use and broader quality/accessibility evaluation remain pending.'),p('Evidence: docs/evidence/test-meta-llama.txt, test-planner-restart.txt, validation.json and media-provenance.json. No production accuracy percentage, latency benchmark or user-traffic claim is made.','SmallPM'),PageBreak()]
story += [h('Hackathon contributions.'),table([['Built for this entry','Pre-existing foundation'],['Focused Android planner screens, source snapshots, candidate extraction and new constrained JNI adapter.','Pocket Memory product concept and visual palette; public llama.cpp inference runtime.'],['Proposal validation, review, stale-source gates, atomic task execution, deduplication and guarded undo.','Meta Llama 3.2 3B open weights and third-party GGUF quantization.'],['Offline workflow/restart verification, screenshots, animation, narrated demo and documentation.','Android, SQLite and the standard Android build toolchain.']],[251,252]),sub('Android preview'),p('Pocket Memory Llama edition: com.pocketmemory.llama, version 0.6.0. The evaluation APK uses Android debug signing and stores sources, proposals and reviewed task batches locally.'),sub('Try the preview'),p('Install the release APK on ARM64 Android 13+. In Model, review Llama terms, download the pinned GGUF in your browser, then import it. In Sources, load the fictional example. Build with Llama, inspect the evidence and review before applying. Allow 2.1 GB for model storage plus runtime space; RAM guidance is estimated.'),sub('Useful next applications'),p('Community workshops, household projects and presentation preparation can use the same explicit-instruction pattern. These are intended extensions; only the client-demo scenario has recorded model verification.'),sub('Project and official references'),p('Repository: github.com/MANTHAN137/pocket-memory-llama\nDemo / APK / checksum: GitHub release v0.6.0-plans\nNew source: MIT; model and vendor terms remain separate.\nEvent: cerebralvalley.ai/e/meta-ai-developer-hackathon\nGuide: event URL + /details; waiver: event URL + /waiver\nDeadline: 5 November 2026, 7:30 AM IST','SmallPM'),p('The demo highlights new hackathon work. No hosted Meta API, Muse model, API credits or bonus-prize eligibility is claimed. Final organizer permission acceptance remains with the participant.','SmallPM')]
def page(canvas,doc):
 w,hh=doc.pagesize;canvas.saveState();canvas.setFillColor(colors.HexColor('#ff8bd2'));canvas.rect(0,hh-12,w,12,fill=1,stroke=0);canvas.setStrokeColor(colors.HexColor('#dad2e3'));canvas.line(46,40,w-46,40);canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#5e5667'));canvas.drawString(46,27,'POCKET MEMORY | BUILT WITH LLAMA | ANDROID PREVIEW');canvas.drawRightString(w-46,27,str(doc.page));canvas.restoreState()
SimpleDocTemplate(str(OUT),pagesize=(595.28,841.89),rightMargin=46,leftMargin=46,topMargin=42,bottomMargin=54,title='Pocket Memory - Built with Llama',author='Manthan Dhole').build(story,onFirstPage=page,onLaterPages=page)
print(OUT)
